#include <iostream>
#include <memory>
#include <vector>
struct Node{ int value; Node* parent{}; std::vector<std::unique_ptr<Node>> children; explicit Node(int v):value(v){} Node& add(int v){auto n=std::make_unique<Node>(v);n->parent=this;children.push_back(std::move(n));return *children.back();} };
int main(){ auto root=std::make_unique<Node>(1); Node& child=root->add(2); std::cout<<child.parent->value<<'\n'; }

#include <iostream>
#include <optional>
#include <ranges>
#include <vector>
std::optional<int> first_even(const std::vector<int>& v){ auto evens=v|std::views::filter([](int x){return x%2==0;}); auto it=evens.begin(); if(it==evens.end())return std::nullopt; return *it; }
int main(){ std::vector<int> v{1,3,8,10}; if(auto x=first_even(v))std::cout<<*x<<'\n'; }
